package appkitc

type mainTemplateData struct {
	ModulePath   string
	Port         string
	PublicDir    string
	PlainHTTP    bool
	RegisterArgs string
}

const runServerTemplateText = `//go:build !wasm

// Code generated by https://webtyp.com. DO NOT EDIT.
package main

import (
	"log"

	"{{.ModulePath}}/config"
)

func main() {
	if err := config.RunServer(); err != nil {
		log.Fatal(err)
	}
}
`

const mainTemplateText = `//go:build !wasm


// Code generated by https://webtyp.com. DO NOT EDIT.
package main

import (
	"log"
	"{{.ModulePath}}/config"
	"webtyp.com/server/httpd"
)

func main() {
	s := httpd.New(httpd.Config{
		Port:      "{{.Port}}",
		PublicDir: "{{.PublicDir}}",
		Gzip:      true,
		Health:    true,
		TLS:       httpd.TLSConfig{PlainHTTP: {{.PlainHTTP}}},
	})
	config.Register({{.RegisterArgs}})

	if err := s.ListenAndServe(); err != nil {
		log.Fatal(err)
	}
}
`

// appServerTemplateText is the server entry point of an app declared as one
// appkit.App value (config.App): appkit builds and serves everything.
const appServerTemplateText = `// Code generated by webtyp.com/appkitc from config/app.go. DO NOT EDIT.
// Why: the server binary of this app; dev tools (database diagram, API explorer) come from webtyp.com/devtools and exist only with -tags dev.
// Architecture: https://github.com/webtyp/appkit/blob/main/docs/ARCHITECTURE.md
// To change what is generated: https://github.com/webtyp/appkitc/blob/main/templates.go

//go:build !wasm

package main

import (
	"log"

	"webtyp.com/appkit/backend"
	"webtyp.com/devtools"
	"webtyp.com/env"
	"webtyp.com/server/httpd"

	"{{.ModulePath}}/config"
	"{{.ModulePath}}/config/services"
)

// Process arguments the dev environment and the self-host supervisor pass to this binary.
const (
	argPort      = "server_port"
	argPublicDir = "server_public_dir"
	argNoCache   = "server_no_cache"
	envDatabase  = "DATABASE_URL"
)

func main() {
	port, publicDir := env.Arg(argPort), env.Arg(argPublicDir)
	if port == "" {
		port = httpd.DefaultPort
	}
	if publicDir == "" {
		publicDir = httpd.DefaultPublicDir
	}
	built, err := backend.Build(config.App, services.Backend, services.Server, env.Get(envDatabase), services.Schema)
	if err != nil {
		log.Fatal(err)
	}
	srv := httpd.New(httpd.Config{
		Port: port, PublicDir: publicDir, Gzip: true, NoCache: env.Arg(argNoCache) == "true", Health: true,
		Logger: config.App.Log, Authn: built.Authn, Authorize: built.Authorize, Report: built.Report, Policy: built.Policy,
	})
	if err := built.Mount(srv.Router(), devtools.Server(services.Schema)...); err != nil {
		log.Fatal(err)
	}
	if _, err := srv.Handler(); err != nil {
		log.Fatal(err)
	}
	log.Fatal(srv.ListenAndServe())
}
`

// migrateTemplateText is the one migration entry point of an appkit.App:
// every module's migration, in App.Modules order.
const migrateTemplateText = `// Code generated by webtyp.com/appkitc from config/app.go. DO NOT EDIT.
// Why: the migration binary: webtyp dev runs it on start and when a model or go.mod changes; the self-host supervisor runs it before each new version (webtyp.com/migrate).
// Architecture: https://github.com/webtyp/appkit/blob/main/docs/ARCHITECTURE.md
// To change what is generated: https://github.com/webtyp/appkitc/blob/main/templates.go

//go:build !wasm

package main

import (
	"flag"
	"fmt"
	"log"

	"webtyp.com/migrate"

	"{{.ModulePath}}/config/services"
)

func main() {
	plan := flag.Bool(migrate.FlagPlan, false, "print one JSON line per column the models no longer have but that still holds data")
	drop := flag.String(migrate.FlagDrop, "", "drop one column, data included: table.column")
	flag.Parse()
	if *drop != "" {
		if err := migrate.Drop(services.Server.Database, services.Schema, *drop); err != nil {
			log.Fatal(err)
		}
		return
	}
	left, err := migrate.App(services.Server.Database, log.Println, services.Schema)
	if err != nil {
		log.Fatal(err)
	}
	if *plan {
		for _, l := range left {
			fmt.Println(migrate.PlanLine(l))
		}
	}
}
`

// removedTemplateText is config/services/removed.go as the generator first writes it: no column removed yet.
// webtyp dev's DATABASE tab rewrites it with the developer's answers; writeOnce never puts it back.
const removedTemplateText = `// Code generated by webtyp.com/appkitc. DO NOT EDIT: webtyp dev's DATABASE tab writes it.
// Why: the columns the models no longer have and where their data went; migrate/main.go reads it, and production repeats each copy without dropping (webtyp.com/ddl Removed).
// Architecture: https://github.com/webtyp/appkit/blob/main/docs/ARCHITECTURE.md
// To change what is generated: https://github.com/webtyp/appkitc/blob/main/templates.go

//go:build !wasm

package services

import "webtyp.com/ddl"

var Removed = []ddl.Removed{}
`

