const migrationsTemplateText = `// Code generated by webtyp.com/appkitc from config/app.go. DO NOT EDIT.
// Why: the migrations of App.Modules in the same order, read by migrate/main.go and by the dev database diagram; build tag !wasm keeps it out of the browser.
// Architecture: https://github.com/webtyp/appkit/blob/main/docs/ARCHITECTURE.md
// To change what is generated: https://github.com/webtyp/appkitc/blob/main/templates.go

//go:build !wasm

package services

import (
	"webtyp.com/ddl"
{{- range .Imports }}
	{{.Alias}} "{{.Path}}"
{{- end }}
)

// Schema is the app's database: every module's migration in App.Modules order, and the columns its models
// no longer have (Removed, in config/services/removed.go).
var Schema = ddl.Schema{
	Steps: []ddl.Step{
{{- range .Steps }}
		{Name: "{{.Name}}", Run: {{if .Run}}{{.Run}}{{else}}{{.Alias}}.Migrate{{end}}},
{{- end }}
	},
	Removed: Removed,
}
`
